 "content": "from collections import Counter


def transform(grid):
    """Move the colored figure to the side of a full 2-rail and mark its far edge."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    rail = next((('h', r) for r in range(h) if all(v == 2 for v in g[r])), None)
    if rail is None:
        rail = next((('v', c) for c in range(w) if all(g[r][c] == 2 for r in range(h))), None)
    if rail is None:
        return g

    points = [(r, c) for r in range(h) for c in range(w)
              if g[r][c] != bg and g[r][c] != 2]
    if not points:
        return g

    if rail[0] == 'h':
        rr = rail[1]
        minr = min(r for r, _ in points)
        maxr = max(r for r, _ in points)
        if minr > rr:
            delta = rr + 1 - minr
            farline = maxr + delta + 1
        else:
            delta = rr - 1 - maxr
            farline = minr + delta - 1
        moved = [(r + delta, c, g[r][c]) for r, c in points]
        for r, c in points:
            g[r][c] = bg
        for r, c, color in moved:
            if 0 <= r < h:
                g[r][c] = color
        if 0 <= farline < h:
            g[farline] = [8] * w
    else:
        cc = rail[1]
        minc = min(c for _, c in points)
        maxc = max(c for _, c in points)
        if minc > cc:
            delta = cc + 1 - minc
            farline = maxc + delta + 1
        else:
            delta = cc - 1 - maxc
            farline = minc + delta - 1
        moved = [(r, c + delta, g[r][c]) for r, c in points]
        for r, c in points:
            g[r][c] = bg
        for r, c, color in moved:
            if 0 <= c < w:
                g[r][c] = color
        if 0 <= farline < w:
            for r in range(h):
                g[r][farline] = 8
    return g


